const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const paradise = ee.Geometry.Point([-121.6219, 39.7596]); // Paradise, CA coordinates
  const area = paradise.buffer(20000); // 20km buffer around Paradise
  const startDate = '2018-11-07';
  const endDate = '2018-11-10';

  // 2. Data Acquisition - MODIS Active Fires
  const fireCollection = ee.ImageCollection('MODIS/006/MCD14ML')
    .filterDate(startDate, endDate)
    .filterBounds(area);

  const collectionSize = fireCollection.size().getInfo();
  console.log(`Fire detections in collection: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No fire detection data found for the specified period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Filter for high confidence fires
  const highConfidenceFires = fireCollection.filter(ee.Filter.gte('confidence', 80));
  const highConfCount = highConfidenceFires.size().getInfo();
  console.log(`High confidence fires (>=80%): ${highConfCount}`);

  // Count total fire pixels in the area
  const fireCounts = fireCollection.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: area,
    scale: 1000,
    maxPixels: 1e9
  });

  const totalFirePixels = fireCounts.get('confidence').getInfo();
  console.log(`Total fire pixels in area: ${totalFirePixels}`);

  if (totalFirePixels === 0) {
    console.log("No fire pixels detected in the area.");
    console.log("<answer>B</answer>");
    return;
  }

  // 4. Validation & Final Answer
  if (highConfCount > 0) {
    console.log(`Active fires detected with high confidence: ${highConfCount}`);
    console.log("<answer>A</answer>");
  } else if (totalFirePixels > 0) {
    console.log("Fire pixels detected but below high confidence threshold.");
    console.log("<answer>A</answer>");
  } else {
    console.log("No fire activity detected.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
